<?php
declare(strict_types=1);
namespace App\Services;
use PDO;use Throwable;
final class ProjectAttachmentService { public function __construct(private readonly PDO $db,private readonly ModuleAttachmentKeyParser $parser,private readonly ModuleAttachmentClient $client,private readonly ModuleManifestValidator $validator,private readonly ProjectConnectionRepository $repository,private readonly ModuleAttachmentRateLimiter $limiter){}public function attach(string $key,int $userId,string $ip,string $platformVersion,string $platformUrl):array{$this->limiter->assertAllowed($userId,$ip);try{$parsed=$this->parser->parse($key);$challenge=bin2hex(random_bytes(32));$response=$this->client->request($parsed['endpoint'],['protocol'=>'gda-module-attach','protocol_version'=>1,'attachment_key'=>$key,'platform'=>['product'=>'gda-plataforma','version'=>$platformVersion,'url'=>$platformUrl],'challenge'=>$challenge]);$manifest=$this->validator->validate($response,$challenge,$parsed['module']);$this->db->beginTransaction();$saved=$this->repository->save($manifest,$parsed['endpoint'],$userId);Logger::activity($saved['action'],'Projeto anexado à Plataforma.','success',$userId,['project_id'=>$saved['project_id'],'product'=>$manifest['module']['product'],'module_instance_id'=>$manifest['connection']['module_instance_id']]);$this->db->commit();$this->limiter->clear($userId,$ip);return $saved+['manifest'=>$manifest];}catch(ModuleAttachmentException $e){if($this->db->inTransaction())$this->db->rollBack();$this->limiter->recordFailure($userId,$ip);$this->safeFailureLog($userId,$e->errorCode);throw $e;}catch(Throwable){if($this->db->inTransaction())$this->db->rollBack();$this->limiter->recordFailure($userId,$ip);$this->safeFailureLog($userId,'internal_error');throw new ModuleAttachmentException('internal_error','Não foi possível anexar o projeto.');}}private function safeFailureLog(int $userId,string $code):void{try{Logger::activity('project.attachment_failed','Falha ao anexar projeto.','failure',$userId,['error_code'=>$code]);}catch(Throwable){}} }
